def load() -> pd.DataFrame:
    return pd.read_csv(
        'data/legal/input/csn-data-book-2024-csv/CSVs/2024_CSN_State_Top_Ten_Report_Categories.csv',
        skiprows=1
    )

def process(load_data) -> pd.DataFrame:
    df = load_data[load_data['Category'] == 'Prizes, Sweepstakes and Lotteries']
    count = df['State'].nunique()
    return pd.DataFrame({'count': [count]})
